public class Main {
    static void mutate(StringBuilder sb, String s) {
        sb.append(" world");
        s = s + " world";
    }

    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder("hello");
        String s = "hello";
        mutate(sb, s);
        System.out.println(sb + " | " + s);
    }
}

